// Emits one item per job-application row that needs a follow-up task today.
// Exact-day matching only, so each row fires exactly once (no <= comparisons
// that would re-fire on every subsequent day).

// The Notion node's simplified output flattens every property to
// `property_` + lowercase name (spaces -> underscores); the title property
// also appears as top-level `name`. dval() normalizes date properties,
// which can come back either as a plain ISO string or as an object like
// { start, end, time_zone }.
const dval = (v) => (v && typeof v === 'object') ? (v.start ?? null) : (v || null);

const rows = $input.all();

const today = $now.setZone('Europe/London').startOf('day');
const yesterday = today.minus({ days: 1 });
const sixDaysAgo = today.minus({ days: 6 });

function isExactDay(rawDate, target) {
  const dateStr = dval(rawDate);
  if (!dateStr) return false;
  const d = DateTime.fromISO(String(dateStr), { zone: 'Europe/London' }).startOf('day');
  if (!d.isValid) return false;
  return d.hasSame(target, 'day');
}

const results = [];

for (const item of rows) {
  const row = item.json;
  const company = row.name || row.property_company || 'Unknown';
  const outreachSent = dval(row.property_outreach_sent);
  const replyReceived = dval(row.property_reply_received);

  if (isExactDay(row.property_applied_date, yesterday) && !outreachSent) {
    results.push({ json: { title: `Message hiring manager - ${company}`, company } });
  }

  if (isExactDay(row.property_outreach_sent, sixDaysAgo) && !replyReceived) {
    results.push({ json: { title: `Second touch or close - ${company}`, company } });
  }
}

return results;
